import {renderPhotoGallery} from './photo-gallery.mjs';
import {readFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {dirname,join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {parseSharedTokens,pixelToken} from './token-values.mjs';

const root=join(dirname(fileURLToPath(import.meta.url)),'..');
const read=path=>readFileSync(join(root,path),'utf8');
const fingerprint=path=>`${path}?v=${createHash('sha256').update(readFileSync(path==='assets/project-media.js'?join(root,'shared/project-media.js'):join(root,'home',path))).digest('hex').slice(0,12)}`;
const sharedTokens=parseSharedTokens(read('shared/tokens.css'));
const dimensions={iconSize:pixelToken(sharedTokens,'size-icon'),menuGlyphSize:pixelToken(sharedTokens,'size-menu-glyph'),statusSize:pixelToken(sharedTokens,'size-status'),avatarSize:pixelToken(sharedTokens,'size-avatar'),avatarMobileSize:pixelToken(sharedTokens,'size-avatar-mobile')};
// Reserve the same dimensions in HTML and CSS, including before images arrive.
const renderSized=(template,values={})=>renderTemplate(template,{...values,...dimensions});
export const escapeText=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));

export function extractBlock(html,marker,tag='div'){
  const start=html.indexOf(marker);
  if(start<0)throw Error(`Missing current component: ${marker}`);
  const tags=new RegExp(`<(/?)${tag}\\b[^>]*>`,'g');tags.lastIndex=start;
  let depth=0,match;
  while((match=tags.exec(html))){depth+=match[1]?-1:1;if(depth===0)return html.slice(start,tags.lastIndex);}
  throw Error(`Unclosed current component: ${marker}`);
}

export function fingerprintAssets(html,{absolute=false}={}){
  return html.replace(/(src|href|data-src)="(\/?)(assets\/[a-z0-9.-]+)(?:\?[^"\s]*)?"/g,(_,a,slash,p)=>`${a}="${absolute||slash?'/':''}${fingerprint(p)}"`)
    .replace(/(srcset|data-srcset)="([^"]+)"/g,(_,a,urls)=>`${a}="${urls.replace(/\/?assets\/[a-z0-9.-]+(?:\?[^,\s]*)?/g,url=>(absolute||url.startsWith('/')?'/':'')+fingerprint(url.replace(/^\//,'').split('?')[0]))}"`);
}
export const absoluteAssets=html=>fingerprintAssets(html,{absolute:true});

// Owned integrations fail rather than silently retaining an older component.
export function replaceExact(source,start,end,replacement){
  if(!start||!end||start===end)throw Error('Owned boundaries must be distinct');
  const count=needle=>source.split(needle).length-1;
  if(count(start)!==1||count(end)!==1)throw Error(`Expected exactly one owned boundary pair: ${start} … ${end}`);
  const from=source.indexOf(start)+start.length,to=source.indexOf(end);
  if(to<from)throw Error(`Reversed owned boundaries: ${start} … ${end}`);
  return source.slice(0,from)+replacement+source.slice(to);
}
export function replaceGeneratedRegion(source,name,markup){
  if(!/^[a-z][a-z0-9-]*$/.test(name))throw Error(`Invalid generated region: ${name}`);
  return replaceExact(source,`<!-- shared:${name}:start -->`,`<!-- shared:${name}:end -->`,'\n'+markup+'\n  ');
}
function replaceComponent(source,name,markup){
  const marker=`<!-- component:${name} -->`;
  if(source.split(marker).length!==2)throw Error(`Expected exactly one component slot: ${name}`);
  return source.replace(marker,()=>markup);
}
export function renderTemplate(template,values){
  const output=template.replace(/\{\{([a-zA-Z]+)\}\}/g,(_,key)=>{
    if(!Object.hasOwn(values,key))throw Error(`Missing canonical template value: ${key}`);
    return values[key];
  });
  if(/\{\{|\}\}/.test(output))throw Error('Unresolved canonical template slot');
  return output;
}
export function getWorkProjects(){
  const projects=JSON.parse(read('shared/work-projects.json'));
  if(!Array.isArray(projects)||!projects.length||new Set(projects.map(project=>project.id)).size!==projects.length)throw Error('Current work projects need unique heading ids');
  return projects;
}
export function renderWorkActions(project=getWorkProjects()[0],{idPrefix}={}){
  return identifyMarkup(fingerprintAssets(renderSized(read('shared/work-actions.html').trim(),project)),idPrefix);
}
export function renderWorkCard(project=getWorkProjects()[0],{idPrefix}={}){
  return identifyMarkup(fingerprintAssets(renderTemplate(read('shared/work-card.html').trim(),{...project,actions:renderWorkActions(project)})),idPrefix);
}
export function renderWorkSection(project=getWorkProjects()[0],{idPrefix}={}){
  return identifyMarkup(renderTemplate(read('shared/work-section.html').trim(),{...project,card:renderWorkCard(project)}),idPrefix);
}
export const renderHomeWorks=()=>getWorkProjects().map(renderWorkSection).join('\n  ');
export function renderHomeIntro(){
  return fingerprintAssets(replaceGeneratedRegion(read('shared/home-intro.html').trim(),'brief-light',renderBrief()));
}
export function renderBack({variant='desktop',absolute=false}={}){
  if(!['desktop','mobile'].includes(variant))throw Error(`Unused Back variant: ${variant}`);
  return fingerprintAssets(renderSized(read('shared/back.html').trim(),{
    backClass:variant==='mobile'?'about-mobile-back ui-back':'ui-back about-desktop-back',
    ariaLabel:variant==='mobile'?' aria-label="Back to homepage"':'',
    label:variant==='mobile'?'':'<span>Back</span>'
  }),{absolute});
}
export function renderArticleHeading({title='About me',showAvatar=true}={}){
  return fingerprintAssets(renderTemplate(read('shared/article-heading.html').trim(),{
    title:escapeText(title),avatar:showAvatar?renderSized(read('shared/about-avatar.html').trim()):''
  }));
}
function identifyMarkup(html,idPrefix){
  if(idPrefix===undefined)return html;
  if(!/^[a-z][a-z0-9-]*$/i.test(idPrefix))throw Error('idPrefix must be an HTML identifier');
  const owned=new Set([...html.matchAll(/\sid="([^"]+)"/g)].map(match=>match[1]));
  const identify=id=>owned.has(id)?idPrefix+'-'+id:id;
  return html.replace(/(\s)(id|for|aria-labelledby|aria-describedby|aria-controls)="([^"]+)"/g,(_,space,key,value)=>`${space}${key}="${value.split(/\s+/).map(identify).join(' ')}"`)
    .replace(/(\s(?:href|xlink:href))="#([^"]+)"/g,(_,key,id)=>`${key}="#${identify(id)}"`)
    .replace(/url\(\s*#([^\s)]+)\s*\)/g,(_,id)=>`url(#${identify(id)})`);
}

// Validate actual markup, excluding script/style text, without treating ordinary
// page anchors or external URLs as component identity references.
export function validateDocumentIds(html,{label='Document'}={}){
  const markup=html.replace(/<!--[\s\S]*?-->/g,'')
    .replace(/(<(script|style)\b[^>]*>)[\s\S]*?(<\/\2\s*>)/gi,(_,open,tag,close)=>open+close);
  const ids=new Set(),references=[];
  let svgDepth=0;
  for(const match of markup.matchAll(/<(\/?)([a-z][\w:-]*)\b((?:"[^"]*"|'[^']*'|[^'">])*)>/gi)){
    const [,closing,rawTag,source]=match,tag=rawTag.toLowerCase();
    if(closing){if(tag==='svg')svgDepth--;continue;}
    if(tag==='svg')svgDepth++;
    const attributes=new Map([...source.matchAll(/(?:^|\s)([^\s=/>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+)))?/g)].map(attribute=>[attribute[1].toLowerCase(),attribute[2]??attribute[3]??attribute[4]??'']));
    if(attributes.has('id')){
      const id=attributes.get('id');
      if(!id||ids.has(id))throw Error(`${label}: ${id?'duplicate':'empty'} id "${id}"`);
      ids.add(id);
    }
    for(const name of ['for','aria-labelledby','aria-describedby','aria-controls']){
      for(const id of (attributes.get(name)||'').split(/\s+/).filter(Boolean))references.push({name,id});
    }
    if(svgDepth>0){
      for(const name of ['href','xlink:href']){
        const value=attributes.get(name)||'';
        if(value.startsWith('#'))references.push({name:'SVG '+name,id:value.slice(1)});
      }
      for(const value of attributes.values())for(const fragment of value.matchAll(/url\(\s*['"]?#([^'"\s)]+)['"]?\s*\)/g))references.push({name:'SVG url()',id:fragment[1]});
    }
    if(tag==='svg'&&/\/\s*$/.test(source))svgDepth--;
  }
  for(const {name,id} of references)if(!ids.has(id))throw Error(`${label}: missing target "${id}" referenced by ${name}`);
  return html;
}
export function renderAboutMain(){
  return fingerprintAssets(replaceComponent(replaceComponent(read('shared/about-main.html').trim(),'back-desktop',renderBack({absolute:true})),'article-heading',renderArticleHeading()));
}
function renderReadingDocument({currentPath='/about/'}={}){
  let page=read('shared/reading-page.html');
  for(const name of ['header','footer'])page=replaceGeneratedRegion(page,name,'  '+renderRegion(name,{article:true,currentPath}));
  page=replaceGeneratedRegion(page,'about-main','  '+renderAboutMain());
  page=replaceGeneratedRegion(page,'brief-preloads',renderBriefPreloads(['dark']));
  return page.replace(/(src|href)="\/(assets\/[a-z0-9.-]+|vendor\/[A-Za-z0-9.-]+|about\/(?:about\.css|about\.js)|mobile-nav\.js|resume-prefetch\.js|analytics\.js)(?:\?[^"\s]*)?"/g,(_,attribute,path)=>`${attribute}="/${fingerprint(path)}"`);
}

// Inventory only the glyphs and brand marks actually rendered by HOME/About.
// Rendering extracts their canonical markup, preserving the real SVGs/wrappers.
export const currentIcons=[
  {id:'arrow-left',name:'Arrow left',group:'interface',source:'Lucide',url:'https://lucide.dev/icons/arrow-left',size:dimensions.iconSize,variants:['light'],usage:'About · Back'},
  {id:'check',name:'Check',group:'interface',source:'Lucide',url:'https://lucide.dev/icons/check',size:dimensions.iconSize,variants:['light','dark'],usage:'Brief · Copied'},
  {id:'menu',name:'Menu / Close',group:'interface',source:'Custom animated glyph',size:dimensions.menuGlyphSize,variants:['closed','open'],usage:`Mobile header · ${sharedTokens['size-target']} control`},
  {id:'claude',name:'Claude',group:'brand',source:'Current SVG asset',size:dimensions.iconSize,variants:['light','dark'],usage:'Brief your AI'},
  {id:'chatgpt',name:'ChatGPT / OpenAI',group:'brand',source:'Current SVG asset',size:dimensions.iconSize,variants:['light','dark'],usage:'Brief your AI'},
  {id:'codex',name:'Codex',group:'brand',source:'Current SVG asset',size:dimensions.iconSize,variants:['light','dark'],usage:'Brief your AI'},
  {id:'cursor',name:'Cursor',group:'brand',source:'Current SVG asset',size:dimensions.iconSize,variants:['light','dark'],usage:'Brief your AI'},
  {id:'copilot',name:'Copilot',group:'brand',source:'Current SVG asset',size:dimensions.iconSize,variants:['light','dark'],usage:'Brief your AI'},
  {id:'availability-dot',name:'Coming Soon dot',group:'status',source:'Custom SVG',size:dimensions.statusSize,variants:['default'],usage:'Work availability · animated in context'}
];

export function renderIcon(name,{variant,theme,idPrefix}={}){
  const definition=currentIcons.find(icon=>icon.id===name);
  if(!definition)throw Error(`Unknown current icon: ${name}`);
  variant=variant||theme||definition.variants[0];
  if(!definition.variants.includes(variant))throw Error(`Unused icon variant: ${name}/${variant}`);
  if(name==='menu'){
    if(idPrefix&&!/^[a-z][a-z0-9-]*$/i.test(idPrefix))throw Error('Icon idPrefix must be an HTML identifier');
    const glyph=extractBlock(renderSized(read('shared/header.html')),'<svg class="menu-glyph"','svg')
      .replaceAll('menu-stroke-shape',`${idPrefix||'icon-menu-'+variant}-stroke-shape`);
    return `<span class="menu-toggle" data-menu-icon="${variant==='open'?'close':'menu'}" aria-hidden="true">${glyph}</span>`;
  }
  if(name==='arrow-left')return absoluteAssets(renderBack().match(/<img\b[^>]*>/)[0]);
  if(name==='availability-dot')return absoluteAssets(extractBlock(renderWorkActions(),'<span class="work-availability"','span').match(/<img\b[^>]*>/)[0]);
  const dark=variant==='dark';
  const button=extractBlock(renderSized(read(`shared/brief-${dark?'dark':'light'}.html`)),'<button ','button');
  if(name==='check')return absoluteAssets(extractBlock(button,'<span class="agent-button-copied"','span').match(/<img\b[^>]*>/)[0]);
  const row=extractBlock(button,'<span class="agent-button-logos"','span');
  const order=dark?['claude','chatgpt','codex','copilot','cursor']:['claude','chatgpt','codex','cursor','copilot'];
  const children=[...row.matchAll(/<span class="(?:agent|footer)-logo-copilot"[^>]*>[\s\S]*?<\/span>|<img\b[^>]*>/g)].map(match=>match[0]);
  if(children.length!==order.length)throw Error('Current Brief logo inventory changed; update the registry');
  return absoluteAssets(children[order.indexOf(name)]);
}

export function getIconCatalog(){
  return currentIcons.map(icon=>({...icon,variants:icon.variants.map(variant=>{
    const html=renderIcon(icon.id,{variant,idPrefix:`catalog-${icon.id}-${variant}`});
    return {id:variant,theme:variant==='dark'?'dark':'light',html,asset:html.match(/src="([^"]+)"/)?.[1]||null};
  })}));
}

// Two prepared HTML variants share behavior, never a runtime theme/asset swap.
export function renderBrief({theme='light',standalone=false,idPrefix}={}){
  if(!['light','dark'].includes(theme))throw Error(`Unused Brief theme: ${theme}`);
  let html=renderSized(read(`shared/brief-${theme}.html`).trim());
  return identifyMarkup(html.replace(/src="(assets\/[a-z0-9.-]+)(?:\?[^"\s]*)?"/g,(_,path)=>`src="${fingerprint(path)}"`),idPrefix);
}

export function renderBriefPreloads(themes){
  const assets=new Set(themes.flatMap(theme=>[...renderBrief({theme}).matchAll(/src="(assets\/[a-z0-9.-]+)(?:\?[^"]*)?"/g)].map(match=>match[1])));
  return [...assets].map(path=>`  <link rel="preload" as="image" type="image/svg+xml" href="/${fingerprint(path)}" fetchpriority="low">`).join('\n');
}

export function renderRegion(name,{article=false,currentPath=article?'/about/':'/'}={}){
  if(!['header','footer'].includes(name))throw Error(`Unknown shared region: ${name}`);
  let html=renderSized(read(`shared/${name}.html`).trim());
  if(name==='footer')html=replaceComponent(html,'brief-dark',renderBrief({theme:'dark'}));
  if(article&&name==='header'){
    const identity=extractBlock(html,'<a class="name identity"','a');
    const name=identity.replace(/^<a\b[^>]*>|<\/a>$/g,'');
    html=html.replace(identity,()=>'<div class="identity about-identity">'+renderBack({variant:'mobile'})+'<a class="name" href="/">'+name+'</a></div>');
    html=html.replace('href="#selected-works"','href="/#selected-works"');
  }
  if(name==='header'){
    const nav=extractBlock(html,'<nav ','nav');
    html=html.replace(nav,()=>nav.replace(/href="(\/[^"#?]*)"/g,(attribute,path)=>path===currentPath ? 'aria-current="page" aria-disabled="true" tabindex="-1"' : attribute));
  }
  return html.replace(/(src|href)="(assets\/[a-z0-9.-]+)(?:\?[^"\s]*)?"/g,(_,attr,path)=>`${attr}="${article?'/':''}${fingerprint(path)}"`);
}

// These names correspond to current, visible components in /ds/.
// Page output, future page composition and DS consume these canonical producers.
export function renderComponent(name,options={}){
  switch(name){
    case 'icon':return renderIcon(options.name,options);
    case 'header':return absoluteAssets(renderRegion('header',{article:options.variant==='article',...(options.currentPath!==undefined?{currentPath:options.currentPath}:{})})).replace('href="#selected-works"','href="/#selected-works"');
    case 'footer':return renderRegion('footer',{article:true});
    case 'portrait':return absoluteAssets(extractBlock(renderHomeIntro(),'<div class="portrait"'));
    case 'about-title':return absoluteAssets(renderArticleHeading(options));
    case 'article-title':return absoluteAssets(renderArticleHeading({title:'404',showAvatar:false,...options}));
    case 'back':{
      if(options.variant==='mobile')return renderBack({variant:'mobile',absolute:true});
      return renderBack({variant:options.variant||'desktop',absolute:true}).replace(' about-desktop-back','');
    }
    case 'navigation-link':return absoluteAssets(extractBlock(renderRegion('header',{currentPath:options.currentPath??'/'}),'<nav ','nav').match(/<a\b[^>]*>About<\/a>/)[0]);
    case 'footer-link':return absoluteAssets(extractBlock(extractBlock(renderRegion('footer'),'<nav class="footer-links"','nav'),'<a ','a'));
    case 'photo-gallery':return renderPhotoGallery({assetUrl:path=>'/'+fingerprint(path)});
    case 'photo-slot':return extractBlock(renderAboutMain(),'<div class="about-photo-placeholder"');
    case 'about-avatar':return absoluteAssets(renderSized(read('shared/about-avatar.html').trim()));
    case 'prose-section':return identifyMarkup('<div class="about-sections about-prose">'+extractBlock(renderAboutMain(),'<section aria-labelledby="design-title"','section')+'</div>',options.idPrefix);
    case 'availability':return absoluteAssets(extractBlock(renderWorkActions(undefined,{idPrefix:options.idPrefix}),'<span class="work-availability"','span'));
    case 'work-section':return absoluteAssets(renderWorkSection(undefined,{idPrefix:options.idPrefix})).replace(/data-src=/g,'src=').replace(/data-srcset=/g,'srcset=');
    case 'work-actions':return absoluteAssets(renderWorkActions(undefined,{idPrefix:options.idPrefix}));
    case 'work-card':{
      const projects=getWorkProjects(),project=options.id?projects.find(project=>project.id===options.id):projects[0];
      if(!project)throw Error(`Unknown current work card: ${options.id}`);
      return absoluteAssets(renderWorkCard(project,{idPrefix:options.idPrefix})).replace(/data-src=/g,'src=').replace(/data-srcset=/g,'srcset=');
    }
    case 'homepage-intro':return absoluteAssets(renderHomeIntro());
    case 'reading-page':return renderRegion('header',{article:true})+renderAboutMain()+renderRegion('footer',{article:true});
    case 'not-found-page':return renderNotFoundContent();
    case 'brief':return absoluteAssets(renderBrief({theme:options.theme||'light',standalone:true,idPrefix:options.idPrefix}));
