  }
}

export function renderProseSection({title,paragraphs=[],id:sectionId},index=0,readingOrder=0){
  if(!Number.isSafeInteger(readingOrder)||readingOrder<0)readingOrder=0;
  const id=sectionId||`article-section-${index+1}`;
  if(!/^[a-z][a-z0-9-]*$/i.test(id))throw Error('Section id must be an HTML identifier');
  return `<section aria-labelledby="${id}"><h2 id="${id}" style="--reading-reveal-order:${readingOrder++}">${escapeText(title)}</h2>${paragraphs.map(text=>`<p style="--reading-reveal-order:${readingOrder++}">${escapeText(text)}</p>`).join('')}</section>`;
}

// A new work page can use the existing About reading template without a mockup.
// This function creates no files and publishes nothing; the caller owns routing.
export function renderArticlePage({title,description='',canonical,intro=[],sections=[],photoPlaceholder=false,leadWorkId=null,showAvatar=false,photoGallery=false}){
  if(!title||!canonical)throw Error('Article title and canonical URL are required');
  const titleMarkup=renderArticleHeading({title,showAvatar});
  let page=renderReadingDocument({currentPath:new URL(canonical,'https://dmitryrybalka.com').pathname});
  page=page.replace(/<title>[\s\S]*?<\/title>/,()=>`<title>${escapeText(title)} — Dmitry Rybalka</title>`)
    .replace(/<meta name="description"[^>]*>/,()=>`<meta name="description" content="${escapeText(description)}">`)
    .replace(/<link rel="canonical"[^>]*>/,()=>`<link rel="canonical" href="${escapeText(canonical)}">`);
  const desktopBack=renderComponent('back').replace('class="ui-back"','class="ui-back about-desktop-back"');
  let readingOrder=0;
  const ordered=markup=>markup.replace(/ style="--reading-reveal-order:\d+"/,'').replace(/^(<[^>]+)>/,`$1 style="--reading-reveal-order:${readingOrder++}">`);
  const sectionsMarkup=()=>sections.map((section,index)=>{
    const start=readingOrder;readingOrder+=1+(section.paragraphs||[]).length;
    return renderProseSection(section,index,start);
  }).join('');
  const main=`<main class="about-main" data-navigation-background>${ordered('<div class="about-title-row">')}${desktopBack}${titleMarkup}</div><div class="about-intro about-prose">${intro.map((text,index)=>ordered(`<p>${escapeText(text)}</p>`)+(photoGallery&&index===0?'</div>'+renderComponent('photo-gallery')+'<div class="about-intro about-prose">':'')).join('')}</div>${photoPlaceholder?ordered(renderComponent('photo-slot')):''}${leadWorkId?ordered('<div class="article-work">')+renderComponent('work-card',{id:leadWorkId})+'</div>':''}<div class="about-sections about-prose">${sectionsMarkup()}</div></main>`;
  page=page.replace(extractBlock(page,'<main ','main'),()=>main).replace(/ data-node-id="[^"]+"/g,'');
  if(photoGallery){
    page=page.replace('</head>',`<link rel="stylesheet" href="/${fingerprint('photo/photo-gallery.css')}"><script src="/${fingerprint('photo/photo-gallery.js')}" defer></script></head>`);
  }
  if(leadWorkId){
    page=page.replace('<link rel="stylesheet" href="/about/',()=>`<link rel="stylesheet" href="/${fingerprint('styles.css')}">\n  <link rel="stylesheet" href="/about/`);
    page=page.replace('</head>',()=>`  <script src="/${fingerprint('assets/project-media.js')}" defer></script>\n</head>`);
  }
  return validateDocumentIds(page,{label:'Article document'});
}

// The live service page and DS specimen share the same reading composition.
// Only the visible main is returned; analytics stay in the route integration.
export function renderNotFoundContent(){
  const document=renderArticlePage({
    title:'404',canonical:'https://dmitryrybalka.com/404/',
    intro:['This page may have moved, or the link may be incorrect.']
  });
  let main=extractBlock(document,'<main ','main');
  const back=renderComponent('back');
  main=main.replace(back.replace('class="ui-back"','class="ui-back about-desktop-back"'),'');
  const titleStart='<div class="about-title-row"';
  if(main.split(titleStart).length!==2)throw Error('404 requires one shared article title row');
  main=main.replace(titleStart,'<div class="not-found-content">'+titleStart);
  const emptySections='<div class="about-sections about-prose"></div>';
  if(main.split(emptySections).length!==2)throw Error('404 requires one empty article sections slot');
  return main.replace(emptySections,`<div class="not-found-actions">${back.replace('<span>Back</span>','<span>Back to home</span>')}</div></div>`);
}

