// Pure readers shared by the HTML renderer and DS catalog builder.
// Token keys omit the leading "--"; values retain their CSS units.
export function parseSharedTokens(source){
  if(typeof source!=='string')throw TypeError('Shared token source must be a string');
  const tokens={};
  const uncommented=source.replace(/\/\*[\s\S]*?\*\//g,'');
  for(const [,key,rawValue] of uncommented.matchAll(/--([a-z0-9-]+)\s*:\s*([^;{}]+);/g)){
    if(Object.hasOwn(tokens,key))throw Error('Duplicate shared token: '+key);
    tokens[key]=rawValue.trim();
  }
  return tokens;
}

// HTML width/height attributes need a number rather than a CSS px string.
export function pixelToken(tokens,key){
  const value=tokens?.[key];
  if(typeof value!=='string'||!/^[-+]?(?:\d+(?:\.\d+)?|\.\d+)px$/.test(value))throw Error('Shared token must use px: '+key);
  const number=Number.parseFloat(value);
  if(!Number.isFinite(number))throw Error('Shared pixel token must be finite: '+key);
  return number;
}

