/* About-specific composition. Shared typography and controls live in site-ui.css. */
.about-page{min-width:0}
.about-page>.header:not(.menu-open){z-index:1}
.reading-viewport-probe{position:fixed;top:0;left:0;width:0;height:100svh;visibility:hidden;pointer-events:none;contain:strict}
.reading-footer-ready .about-main{min-height:var(--reading-viewport-height)}
.reading-footer-overlap .about-main{position:sticky;top:var(--reading-sticky-top);z-index:0;transform-origin:center bottom}
html[data-reading-footer-covered="true"]{background:var(--color-inverse);overscroll-behavior-y:none}
.about-main{width:var(--width-page);margin:0 auto;padding-top:107px;padding-bottom:86px}
.about-title-row{display:grid;grid-template-columns:120px minmax(0,var(--width-prose)) 120px;gap:var(--space-10);align-items:center;margin-bottom:35px}
.about-title{display:flex;align-items:center;gap:var(--space-4);min-height:64px}
.about-title h1{margin:0;text-wrap:pretty}
.about-avatar{position:relative;flex:none;width:var(--size-avatar);height:var(--size-avatar);overflow:hidden;border-radius:var(--radius-pill);background:var(--color-surface)}
.about-avatar img{display:block;width:100%;height:100%;object-fit:cover}
.header .about-mobile-back{display:none}
.about-prose{width:var(--width-prose);margin-inline:auto;text-wrap:pretty;overflow-wrap:break-word}
.about-prose p{margin:0}
.about-intro{display:flex;flex-direction:column;gap:var(--space-4);margin-bottom:var(--space-6)}
.about-photo-placeholder{width:100%;height:290px;margin-bottom:var(--space-6);border-radius:var(--radius-placeholder);background:var(--color-surface)}
.about-sections{display:flex;flex-direction:column;gap:var(--space-4)}
.about-sections section{display:flex;flex-direction:column;gap:var(--space-4)}
.about-sections h2{display:flex;align-items:center;min-height:60px;margin:0}
/* First-paint entrance works without JavaScript. The reading runtime only
   postpones blocks that have not yet reached the viewport. Layout stays fixed. */
@keyframes reading-content-enter{from{opacity:0;transform:translateY(var(--offset-reading-reveal))}to{opacity:1;transform:none}}
@media(prefers-reduced-motion:no-preference){
  .about-main :where(.about-title-row,.about-intro > p,.about-photo-placeholder,.article-work,.about-sections > section > *){animation:reading-content-enter var(--duration-reading-reveal) var(--ease-reading-reveal) var(--reading-reveal-delay,calc(var(--delay-reading-step) * var(--reading-reveal-order,0))) backwards}
  .about-main [data-reading-reveal="pending"]{animation:none;opacity:0;transform:translateY(var(--offset-reading-reveal))}
  .about-main [data-reading-reveal="shown"]{animation:none}
}
