@media(max-width:983px) and (min-width:768px) and (pointer:fine){
  .about-main{width:calc(100% - var(--gutter-page) * 2)}
  .about-title-row{grid-template-columns:120px minmax(0,1fr);gap:var(--space-10)}
  .about-prose{width:min(100%,var(--width-prose))}
  .about-page .header{width:calc(100% - var(--gutter-page) * 2)}
}
@media(max-width:767px), (max-width:1023px) and (pointer:coarse){
  .about-page .header{top:calc(17px + env(safe-area-inset-top));min-height:var(--height-control)}
  .about-page .header .about-identity{display:flex;align-items:center;gap:var(--space-5)}
  .header .about-mobile-back{display:inline-flex;width:var(--width-back-mobile);padding:var(--space-2) var(--space-6)}
  .about-desktop-back{display:none}
  .about-page .header .name{white-space:nowrap}
  .about-main{width:calc(100% - var(--gutter-page) * 2);max-width:var(--width-mobile);padding-top:calc(104px + env(safe-area-inset-top));padding-bottom:112px}
  .about-avatar{width:var(--size-avatar-mobile);height:var(--size-avatar-mobile)}
  .about-title-row{display:block;margin-bottom:42px}
  .about-title{width:100%}
  .about-prose{width:100%}
  .about-intro{gap:var(--space-5);margin-bottom:var(--space-7)}
  .about-photo-placeholder{height:222px;margin-bottom:var(--space-7)}
  .about-sections,.about-sections section{gap:var(--space-5)}
  .about-sections h2{min-height:0}
  html:not([data-mobile-nav-ready="true"]) .about-main{padding-top:200px}
}
@media(max-width:359px){
  .about-page .header:not(.menu-open) .about-identity{gap:var(--space-3)}
