}
@media(prefers-reduced-motion:reduce){.ui-back{transition:none}}

/* Page gutters belong to the reading shell; an embedded card fills it. */
.article-work>.work-card{width:100%;max-width:100%}
@media(min-width:768px) and (max-width:983px) and (pointer:fine){
.article-work>.work-card{flex-direction:column;align-items:stretch}
