export const photos=[
  ['office','office',203,755,220,293,'A laptop by the window overlooking the city','cover'],
  ['0741','7b03b',1230,748,232,309,'Snow-covered mountain', 'cover'],
  ['4440','3f816',694,733,226,288,'Hot-air balloons over Cappadocia','balloons'],
  ['8235','e0372',1483,332,220,293,'Rocky winter landscape','cover'],
  ['7013','ab055',696,1045,227.822,335.737,'Coffee brewing outdoors','coffee'],
  ['7375','e2d31',1485,905,219,323,'Rocky coast and blue sea','coast'],
  ['5146','fd9a1',203,317,293,390,'Paddleboards beside an autumn river','cover'],
  ['5291','fcfe0',519,405,405,304,'Paddleboarding together on a quiet river','cover'],
  ['1561','91b2a',947,189,260,346,'Cycling through an autumn forest','cover'],
  ['3989','50894',1230,432,226,301,'A small collection of everyday objects','cover'],
  ['6332','b355d',947,557,260,346,'A bright yellow interior','cover'],
  ['4632','fddbd',448,733,223.215,328.947,'Paddling on the river under summer clouds','paddle']
];
export function renderPhotoGallery({assetUrl=path=>'/'+path}={}){
  const items=photos.map(([id,file,x,y,w,h,alt,crop])=>`<div class="photo-gallery-card photo-crop-${crop}" data-photo-x="${x}" data-photo-y="${y}" data-photo-width="${w}" data-photo-height="${h}" style="--photo-ratio:${w}/${h}"><div class="photo-gallery-crop"><img src="${assetUrl('assets/photo-'+file+'.png')}" alt="${alt}" width="${Math.round(w)}" height="${Math.round(h)}" loading="lazy" decoding="async" draggable="false"></div></div>`).join('');
  return `<section class="photo-gallery" aria-label="Personal photo gallery"><div class="photo-gallery-field" tabindex="0" role="region" aria-label="Infinite photo gallery. Drag to explore. Use arrow keys to move; Home to reset." aria-describedby="photo-gallery-hint">${items}</div><p class="photo-gallery-hint" id="photo-gallery-hint"><span class="photo-gallery-drag-hint">Drag to explore</span><span class="photo-gallery-touch-hint">Swipe to explore</span><span aria-hidden="true"> · </span>Little moments, in every direction</p></section>`;
}

