/* Progressive enhancement: the original eleven photographs remain browsable without JS. */
.photo-gallery{margin-block:var(--space-7);width:100%;position:relative}
.photo-gallery-field{position:relative;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;padding:20px;max-height:620px;overflow:auto;border-radius:var(--radius-placeholder);outline-offset:6px}
.photo-gallery-card{position:relative;overflow:hidden;border-radius:12px;aspect-ratio:var(--photo-ratio);background:var(--color-surface);isolation:isolate}
.photo-gallery-crop{position:absolute;inset:0;overflow:hidden;border-radius:12px}
.photo-gallery-card img{display:block;width:100%;height:100%;object-fit:cover;pointer-events:none;user-select:none;-webkit-user-drag:none}
.photo-crop-balloons img{position:absolute;left:-77.51%;width:226.58%;max-width:none}
.photo-crop-coast img{position:absolute;top:-10.23%;left:-.09%;height:120.93%;width:100.17%;max-width:none}
.photo-crop-coffee .photo-gallery-crop{inset:-3.57% -28.43% -15% -10%}
.photo-crop-coffee img{position:absolute;left:-39.05%;top:-.03%;height:100.06%;width:168.66%;max-width:none}
.photo-crop-paddle .photo-gallery-crop{inset:-18.21% -35% -29.35% -27.37%}
.photo-gallery-hint{color:var(--color-muted);font-size:var(--type-meta,16px);line-height:var(--line-compact);text-align:center;margin:18px 0 0}
.photo-gallery-touch-hint{display:none}
.photo-gallery-enhanced{width:min(calc(100vw - 40px),1264px);left:50%;transform:translateX(-50%)}
.photo-gallery-enhanced .photo-gallery-field{display:block;height:600px;max-height:none;padding:0;overflow:hidden;cursor:grab;touch-action:pan-y;user-select:none;-webkit-user-select:none;mask-image:linear-gradient(to right,transparent,#000 4%,#000 96%,transparent),linear-gradient(to bottom,transparent,#000 5%,#000 94%,transparent);mask-composite:intersect}
.photo-gallery-enhanced .photo-gallery-card{position:absolute;left:0;top:0;will-change:transform;transform-origin:center;contain:layout paint;}
.photo-gallery-enhanced[data-dragging] .photo-gallery-field{cursor:grabbing}
.photo-gallery-field:focus-visible{outline:var(--focus-width) solid var(--color-text);outline-offset:4px}
@media(max-width:767px), (max-width:1023px) and (pointer:coarse){
 .photo-gallery-field{grid-template-columns:repeat(2,minmax(0,1fr))}
 .photo-gallery-enhanced .photo-gallery-field{height:440px}
 .photo-gallery-drag-hint{display:none}.photo-gallery-touch-hint{display:inline}
 .photo-gallery-hint{font-size:14px;max-width:280px;margin-inline:auto}
